 14	/**
 15	 * Advances cooperative alliance life: an enabled account with no alliance and no outstanding
 16	 * application applies to the alliance its tier would join. The host owns membership; an existing
 17	 * membership and a pending application leave the account alone, and an alliance that already
 18	 * rejected it is skipped by the choice, so the pass never spams the same alliance. An account
 19	 * every alliance has refused founds its own club instead of staying alone forever (DEF-017).
 20	 */
 21	class AdvanceAiAllianceLifeAction
 22	{
 23	    /** The first club's tag; later founders derive their own from their name. */
 24	    private const FIRST_ALLIANCE_TAG = 'ORBITAL';
 25	
 26	    public function handle(): int
 27	    {
 28	        $advanced = $this->foundFirstAlliance();
 29	
 30	        foreach (AiProfile::query()->where('enabled', true)->pluck('player_id') as $playerId) {
 31	            if ($this->alreadyEngaged($playerId)) {
 32	                continue;
 33	            }
 34	
 35	            if (app(ApplyAiAllianceAction::class)->handle($playerId)->successful) {
 36	                $advanced++;
 37	            }
 38	        }
 39	
 40	        // The leader half of the same social pass: decide pending applications (DEF-006/007)
 41	        // and answer buddy requests from known contacts (DEF-009).
 42	        $advanced += app(ReviewAiAllianceApplicationsAction::class)->handle();
 43	        $advanced += app(ReviewAiBuddyRequestsAction::class)->handle();
 44	
 45	        // A real player every alliance has refused founds their own club (DEF-017):
 46	        // the same first-mover move the first founder made, one per pass so the
 47	        // rest apply to the new club next pass instead of founding one club each.
 48	        $advanced += $this->foundWhenLockedOut();
 49	
 50	        return $advanced;
 51	    }
 52	
 53	    /**
 54	     * A universe with no alliance has nothing to apply to, so the first eligible
 55	     * account founds one — the same first-mover move a player makes — and the
 56	     * rest apply to it on later passes (DISC-012).
 57	     */
 58	    private function foundFirstAlliance(): int
 59	    {
 60	        if (Alliance::query()->exists()) {
 61	            return 0;
 62	        }
 63	
 64	        $founderId = AiProfile::query()->where('enabled', true)->orderBy('player_id')->value('player_id');
 65	
 66	        if ($founderId === null || $this->alreadyEngaged($founderId)) {
 67	            return 0;
 68	        }
 69	
 70	        return $this->foundAlliance($founderId, self::FIRST_ALLIANCE_TAG);
 71	    }
 72	
 73	    /**
 74	     * The second and later alliances come from the same move as the first: an account
 75	     * that cannot join anywhere founds its own. A farm (no rank) is not a founder.
 76	     */
 77	    private function foundWhenLockedOut(): int
 78	    {
 79	        if (!Alliance::query()->exists()) {
 80	            return 0;
 81	        }
 82	
 83	        foreach (AiProfile::query()->where('enabled', true)->orderBy('player_id')->pluck('player_id') as $playerId) {
 84	            if ($this->alreadyEngaged($playerId)) {
 85	                continue;
 86	            }
 87	
 88	            if ((int) Highscore::query()->where('player_id', $playerId)->value('general_rank') <= 0) {
 89	                continue;
 90	            }
 91	
 92	            if (app(AllianceChoice::class)->hasOpenCandidate($playerId)) {
 93	                continue;
 94	            }
 95	
 96	            return $this->foundAlliance($playerId, $this->tagFor($playerId));
 97	        }
 98	
 99	        return 0;
100	    }
101	
102	    /**
103	     * The tag is the founder's own name, not a module list: a club takes its founder's
104	     * identity, and the host enforces 3-8 chars and uniqueness.
105	     */
106	    private function tagFor(int $founderId): string
107	    {
108	        $username = (string) User::query()->whereKey($founderId)->value('username');
109	        $base = substr(strtoupper((string) preg_replace('/[^A-Z0-9]/', '', $username)) . 'CLUB', 0, 6);
110	
111	        foreach (['', '2', '3', '4', '5'] as $suffix) {
112	            $tag = $base . $suffix;
113	
114	            if (!Alliance::query()->where('alliance_tag', $tag)->exists()) {
115	                return $tag;
116	            }
117	        }
118	
119	        // ponytail: six candidates from one name cover a handful of founders; a
120	        // denser universe falls through to a tag createAlliance will refuse, and
121	        // the next pass retries.
122	        return $base;
123	    }
124	
125	    private function foundAlliance(int $founderId, string $tag): int
126	    {
127	        try {
128	            app(AllianceService::class)->createAlliance($founderId, $tag, ucfirst(strtolower($tag)) . ' Pact');
129	        } catch (Exception $exception) {
130	            // A cooldown or tag collision leaves the universe unchanged; the next
131	            // pass retries with the next eligible account.
132	            return 0;
133	        }
134	
135	        return 1;
136	    }
137	
138	    private function alreadyEngaged(int $playerId): bool
139	    {
140	        $user = User::query()->find($playerId);
141	
142	        if ($user === null || $user->alliance_id !== null) {
143	            return true;
144	        }
145	
146	        return AllianceApplication::query()
147	            ->where('user_id', $playerId)
148	            ->where('status', AllianceApplication::STATUS_PENDING)
149	            ->exists();
150	    }
151	}

