13	/**
14	 * Applies the account to the alliance its tier would actually join, through the host's own
15	 * application path. The choice is re-read at apply time so the pass and the host state never
16	 * disagree; the host still decides whether the application is accepted.
17	 */
18	class ApplyAiAllianceAction
19	{
20	    public function handle(int $playerId): AiActionResult
21	    {
22	        $alliance = app(AllianceChoice::class)->choose($playerId);
23	
24	        if ($alliance === null) {
25	            return AiActionResult::rejected(AiQueueActionReason::NoSuitableAlliance);
26	        }
27	
28	        try {
29	            app(AllianceService::class)->applyToAlliance($playerId, $alliance->id, $this->applicationMessage($playerId));
30	
31	            return AiActionResult::succeeded(AiQueueActionReason::AllianceApplied);
32	        } catch (Exception $exception) {
33	            return AiActionResult::rejected($exception->getMessage());
34	        }
35	    }
36	
37	    private function applicationMessage(int $playerId): string
38	    {
39	        $archetype = AiProfile::query()->where('player_id', $playerId)->first(['archetype'])?->archetype;
40	
41	        return match ($archetype) {
42	            AiArchetype::Miner => 'Active miner looking for a stable alliance to trade deuterium for protection.',
43	            AiArchetype::Fleeter => 'Active fleeter looking for an alliance to coordinate hits and ACS.',
44	            AiArchetype::Turtle => 'Defensive player seeking a quiet alliance for mutual protection.',
45	            AiArchetype::Trader => 'Trader seeking an alliance to move resources and share market opportunities.',
46	            AiArchetype::Casual => 'Casual player looking for an active, friendly alliance.',
47	            default => 'Looking for an active alliance.',
48	        };
49	    }
